import {
    createUserWithEmailAndPassword,
    getAuth,
    sendPasswordResetEmail,
    signInWithEmailAndPassword,
    signOut,
} from 'firebase/auth'
import { initializeApp } from 'firebase/app'
export default function () {
    const firebaseConfig = {
        apiKey: 'AIzaSyD2mlSVl5nKOBS7cA_XypDy4UBqPz68AHQ',
        authDomain: 'vnhappy7-dev.firebaseapp.com',
        projectId: 'vnhappy7-dev',
        storageBucket: 'vnhappy7-dev.appspot.com',
        messagingSenderId: '565779280846',
        appId: '1:565779280846:web:5fe8817b8c1bb119efb19f',
        measurementId: 'G-YLRX0JPRDV',
    }
    initializeApp(firebaseConfig)

    const resolveAuthResult = async (userCredential) => {
        const firebaseUser = userCredential.user
        const accessToken = await firebaseUser.getIdToken()
        console.log('user accessToken: ', accessToken)
        console.log('firebaseUser: ', firebaseUser)
        return { firebaseUser, accessToken }
    }

    const firebaseLogin = async (email, password) => {
        const userCredential = await signInWithEmailAndPassword(getAuth(), email, password)
        return resolveAuthResult(userCredential)
    }

    const firebaseSignup = async (email, password) => {
        const userCredential = await createUserWithEmailAndPassword(getAuth(), email, password)
        return resolveAuthResult(userCredential)
    }

    const firebaseSendPasswordResetEmail = async (email) => {
        await sendPasswordResetEmail(getAuth(), email)
    }

    return {
        firebaseLogin,
        firebaseSignup,
        firebaseSendPasswordResetEmail,
        getAuth,
        firebaseLogout: signOut,
    }
}
